// VENDORED VERBATIM, NOT FORKED. Source: https://github.com/guenchi/Goeteia
// rt/sexpr.mjs at commit 5b45908, md5 8b6f586a597bbf12225637d96c589d51 of the original file.
// The package exports "./sexpr" now, but the published 1.7.1 predates that
// export, so a dependency on it would not resolve; this copy stands in until
// a release carries the export, and is then deleted in favour of the dependency.
// Nothing below this line is edited. The golden fixtures beside it say so:
// sexpr-vectors.json (md5 0a6425ef929941f2c8ab2b871a889f7e) and sexpr-escape-vectors.json (md5 8ff54ea9f243e8f8684dac43138ae270).

// sexpr.mjs -- the s-expression wire codec for consumers that do not
// compile through this toolchain: a plain page, a React app, any
// JavaScript that has to speak to an igropyr node.
//
// This is the THIRD implementation of one wire format (igropyr's
// Scheme one is the authority, lib/web/sexpr.ss is the Goeteia one),
// so it is held to a golden fixture generated by that authority --
// test/sexpr-vectors.json -- and never to the other implementations.
// Twins drift; a shared oracle is the only thing that catches it.
//
// Zero dependencies, one ES module, same source in a browser and in
// node.  The only host machinery it reaches for is TextEncoder /
// TextDecoder (the latter in fatal mode, for rpc replies) and
// DataView; base64 is implemented here rather than through atob/btoa,
// whose boundaries are not the ones this format draws.
//
// ---------------------------------------------------------------- //
// THE VALUE MODEL
// ---------------------------------------------------------------- //
//
//   wire                     JavaScript
//   ----------------------   -----------------------------------
//   (a b c)                  Array
//   ()                       [] (an empty Array)
//   (a . b)                  DottedList {items, tail}
//   symbol                   Sym {name}          -- sym("get-user")
//   "text"                   string
//   exact integer            BigInt              -- ALWAYS
//   exact ratio              Ratio {num, den}    -- BigInt fields
//   flonum (#f8"...")        number              -- ALWAYS
//   #(a b)                   Vec {items}
//   #vu8"..."                Uint8Array
//   #t / #f                  boolean
//
// The two ALWAYS are one decision, and it is the only unambiguous one
// available: JavaScript cannot tell 1 from 1.0, so exactness cannot be
// recovered from the value at write time.  A BigInt is therefore always
// an exact integer and a number is always a flonum -- `write(42n)` puts
// `42` on the wire and `write(42)` puts `#f8"..."` on it.  A consumer
// that means the exact integer must say so with a BigInt.
//
// ---------------------------------------------------------------- //
// SAFETY
// ---------------------------------------------------------------- //
//
// One caveat on flonums: the wire carries the eight IEEE bytes, so
// every double crosses bit-exactly INCLUDING a signed zero.  A NaN's
// payload is a different matter -- ECMAScript exposes a single NaN
// value and does not promise a payload survives a store and load, so
// what crosses is "a NaN", and the tests pin what this engine does
// rather than a portable guarantee.
//
// One caveat on flonums: the wire carries the eight IEEE bytes, so
// every double crosses bit-exactly, a signed zero included.  A NaN's
// PAYLOAD is a different matter -- ECMAScript exposes one NaN value
// and does not promise a payload survives a store and a load -- so
// what is guaranteed to cross is "a NaN", and the tests pin what this
// engine does rather than a portable rule.
//
// A recursive-descent parser, not a host reader: no eval, a depth limit
// (64 by default), a token cap (65536).  Every refusal ABOUT THE INPUT
// is a SexprError carrying a position, so a reply from anywhere may be
// handed to read() and the worst case is a positioned error.  A caller
// mistake -- a non-string input, an option this module does not have --
// is a TypeError or a RangeError instead, and deliberately so: those
// are bugs in the calling code, not data from the peer.
//

export const MAX_DEPTH = 64;
export const MAX_TOKEN = 65536;
export const MAX_SPINE = 1000000;

export class SexprError extends Error {
    constructor(message, position) {
        super(`${message} @${position}`);
        this.name = 'SexprError';
        this.detail = message;
        // an index into the input, in CODE POINTS -- what the authority
        // counts.  (lib/web/sexpr.ss counts UTF-8 bytes instead, because
        // that runtime's strings are byte strings; docs/sexpr.md has the
        // table.  A position is local diagnostic metadata, never on the
        // wire.)  A UTF-16 offset would drift by one per astral
        // character and match neither.
        this.position = position;
    }
}

export class Sym {
    constructor(name) {
        if (typeof name !== 'string') throw new TypeError('Sym wants a string');
        this.name = name;
        Object.freeze(this);
    }
    toString() { return this.name; }
}
export const sym = name => new Sym(name);

// `(a . b)` where b is NOT a list.  A dotted tail that is itself a
// list is not a distinct datum -- `(a . (b c))` IS `(a b c)`, and
// `(a . ())` IS `(a)` -- so those shapes are not representable here:
// two spellings of one value is how a codec starts disagreeing with
// itself about equality.  Use dotted(), which folds them.
export class DottedList {
    constructor(items, tail) {
        if (!Array.isArray(items) || items.length === 0)
            throw new TypeError('DottedList wants a non-empty items array');
        if (Array.isArray(tail) || tail instanceof DottedList)
            throw new TypeError(
                'a dotted tail that is a list is just a longer list; '
                + 'use dotted(items, tail) to fold it');
        // a copy, frozen: the caller's array is theirs to mutate, and
        // emptying it afterwards would turn this into `( . tail)`,
        // which reads back as an entirely different datum
        this.items = Object.freeze(denseElements(items));
        this.tail = tail;
        Object.freeze(this);
    }
}

// items . tail, folded: the only constructor that accepts every tail.
export function dotted(items, tail) {
    if (!Array.isArray(items) || items.length === 0)
        throw new TypeError('dotted wants a non-empty items array');
    if (Array.isArray(tail))
        return [...denseElements(items), ...denseElements(tail)];
    if (tail instanceof DottedList)
        return new DottedList([...denseElements(items), ...tail.items], tail.tail);
    return new DottedList(items, tail);
}

export class Vec {
    constructor(items) {
        if (!Array.isArray(items)) throw new TypeError('Vec wants an array');
        this.items = Object.freeze(denseElements(items));
        Object.freeze(this);
    }
}

// An exact ratio.  The policy in full, because "we refuse anything
// non-canonical" would be a simpler sentence and a false one:
//
//   * the INPUT is wide -- `new Ratio(2n, 4n)` and `new Ratio(1n, -2n)`
//     are accepted and normalized on construction (lowest terms, sign
//     on the numerator), so what reaches the wire is `1/2` and `-1/2`;
//   * the OUTPUT is narrow -- the authority's arithmetic reduces, so
//     those canonical bytes are the only ones it would ever produce
//     for the same value, and a peer reading them back gets the value
//     that was meant;
//   * a ratio that reduces to a WHOLE NUMBER is refused rather than
//     normalized, because normalizing it would silently change the
//     datum's type: `4/2` is the integer 2 on this wire, and a caller
//     who wrote a Ratio and got an integer back has been surprised
//     quietly.  `ratio()` collapses it to a BigInt on purpose; the
//     constructor says so and stops.
//   * a zero denominator is refused outright -- it is not a number.
// The normalisation both entries need, in one place.  What they do NOT
// share is what happens afterwards: the constructor refuses an integral
// ratio, the factory collapses it to a BigInt.  So this is not "one of
// them delegates to the other" -- `new Ratio(4n,2n)` must throw while
// `ratio(4n,2n)` must answer 2n, and both need the reduction finished
// before they can tell which case they are in.
//
// `ratio()` ends by calling `new Ratio(n, d)`, which normalises what is
// already normalised.  That is NOT redundant work to be removed: both
// are public entries, both take whatever a caller hands them, and the
// constructor's normalisation is its own promise to anyone who calls it
// directly -- `new Ratio(1n, -2n)` has to work whether or not some
// other function happened to tidy the arguments first.  A part may not
// skip its own contract because another part usually runs first.
//
// The observable consequence, so that nobody reads a green suite as
// coverage: a SIGN mutation here is invisible through ratio()'s Ratio
// branch.  That branch hands its result to `new Ratio`, which runs
// this same function again, and applying a sign flip twice undoes it
// -- measured, not argued.  So a green reading from that path is not
// evidence about this line; test sign behaviour through the
// constructor, where one application is all there is.
//
// Not every mutation is invisible that way: skipping the reduction
// (`g = 1n`) changes both entries and reddens both sides' assertions,
// because reduction has no self-inverse to hide behind.  The rule is
// about the SHAPE of the mutation, not about the entry.
//
// The factory's own normalisation is observable in exactly one place,
// the `d === 1n` branch that returns `n` without building a Ratio,
// which is why all four sign combinations of that collapse are
// asserted in test/sexpr-mjs.mjs.
//
// It was two verbatim copies until the mutation tool refused to touch
// either: "NOT LANDED, occurrences: 2".  Both copies were reached by
// assertions, so this was never "untested" -- it was UNPROVABLE, and
// those are different entries on a coverage ledger.  A single-point
// mutation cannot land on text that appears twice, so no experiment
// could show which copy an assertion had exercised.
//
// `who` spells the caller's own name into the messages.  The four
// messages are four distinct strings and callers match on them; the
// case difference between "Ratio wants" and "ratio wants" is part of
// the behaviour, not an accident of style.
function normalize(num, den, who) {
    if (typeof num !== 'bigint' || typeof den !== 'bigint')
        throw new TypeError(`${who} wants BigInt numerator and denominator`);
    if (den === 0n) throw new RangeError(`${who} with zero denominator`);
    let n = num, d = den;
    if (d < 0n) { n = -n; d = -d; }
    const g = gcd(n < 0n ? -n : n, d);
    return [n / g, d / g];
}

export class Ratio {
    constructor(num, den) {
        const [n, d] = normalize(num, den, 'Ratio');
        // An integral "ratio" is not a value this wire has: the peer's
        // arithmetic reduces, so 4/2 is the integer 2 there and a
        // Ratio{4,2} here would serialize to a datum that reads back as
        // something of a different type.  Use ratio(), which collapses.
        if (d === 1n)
            throw new RangeError(
                `${num}/${den} reduces to the integer ${n}; use ratio() or a BigInt`);
        this.num = n;
        this.den = d;
        Object.freeze(this);
    }
}
function gcd(a, b) { while (b) { [a, b] = [b, a % b]; } return a || 1n; }

// A ratio that reduces to a whole number is an integer on this wire,
// not a ratio: the authority's `/` reduces, so 4/2 arrives as 2.
export const ratio = (num, den) => {
    // `new Ratio` re-normalizes what this hands it, so a SIGN defect in
    // normalize is invisible through this entry: applying the flip
    // twice self-corrects (measured).  A green reading here is not
    // coverage of normalize's sign handling -- that lives on the
    // constructor, which applies it once.  What IS observable here is
    // the branch below that returns `n` directly, and its four sign
    // combinations are asserted in test/sexpr-mjs.mjs.
    const [n, d] = normalize(num, den, 'ratio');
    return d === 1n ? n : new Ratio(n, d);
};

// ---------------------------------------------------------------- //
// base64, exactly where the authority draws its lines
// ---------------------------------------------------------------- //
//
// The decoder ignores '=' wherever it appears, takes six bits from
// every other character, and REQUIRES the bits left over after the
// last whole byte to be zero.  That last rule is why `#vu8"A"` is an
// empty bytevector (six leftover zero bits) while `#vu8"AB"` is an
// error (four leftover bits carrying a 1).  Guessing at this boundary
// would put two implementations one byte apart on a rare input.

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const B64_INDEX = (() => {
    const m = new Int8Array(128).fill(-1);
    for (let i = 0; i < B64.length; i++) m[B64.charCodeAt(i)] = i;
    return m;
})();

export function base64Decode(text, fail) {
    if (typeof text !== 'string')
        throw new TypeError('base64Decode wants a string');
    if (typeof fail !== 'function')
        throw new TypeError('base64Decode wants a failure callback');
    const out = [];
    let acc = 0, bits = 0;
    for (let i = 0; i < text.length; i++) {
        const c = text.charCodeAt(i);
        if (c === 61 /* = */) continue;
        const v = c < 128 ? B64_INDEX[c] : -1;
        if (v < 0) return fail('bad base64 character');
        acc = (acc << 6) | v;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            out.push((acc >> bits) & 0xff);
            acc &= (1 << bits) - 1;
        }
    }
    if (acc !== 0) return fail('non-canonical base64 tail');
    return Uint8Array.from(out);
}

export function base64Encode(bytes) {
    // a plain array of out-of-range numbers used to produce text like
    // "undefinedA==" rather than a refusal
    if (!(bytes instanceof Uint8Array)) {
        if (!Array.isArray(bytes))
            throw new TypeError('base64Encode wants a Uint8Array or an array of bytes');
        // denseElements in one pass: `every` skips holes and reads
        // inherited indices, so base64Encode(Array(1)) invented a zero
        // byte -- or borrowed Array.prototype[0] if one was set
        bytes = denseElements(bytes);
        for (const b of bytes)
            if (!Number.isInteger(b) || b < 0 || b > 255)
                throw new TypeError(`base64Encode wants bytes; got ${b}`);
    }
    let s = '';
    for (let i = 0; i < bytes.length; i += 3) {
        const a = bytes[i], b = bytes[i + 1], c = bytes[i + 2];
        s += B64[a >> 2];
        s += B64[((a & 3) << 4) | ((b ?? 0) >> 4)];
        s += b === undefined ? '=' : B64[((b & 15) << 2) | ((c ?? 0) >> 6)];
        s += c === undefined ? '=' : B64[c & 63];
    }
    return s;
}

const F64_VIEW = new DataView(new ArrayBuffer(8));
function flonumToB64(x) {
    F64_VIEW.setFloat64(0, x, true);
    return base64Encode(new Uint8Array(F64_VIEW.buffer.slice(0)));
}
function b64ToFlonum(bytes) {
    for (let i = 0; i < 8; i++) F64_VIEW.setUint8(i, bytes[i]);
    return F64_VIEW.getFloat64(0, true);
}

// ---------------------------------------------------------------- //
// the grammar's own character classes
// ---------------------------------------------------------------- //

const isWs = c => c === ' ' || c === '\t' || c === '\n' || c === '\r';
const isDelim = c => isWs(c) || c === '(' || c === ')' || c === '"';
const SYMBOL_PUNCT = new Set(['-', '+', '*', '/', '<', '>', '=', '?', '!',
                              '.', '_', '%', '&', '^', '~', ':', '@']);
const isDigit = c => c >= '0' && c <= '9';
const isSymbolChar = c =>
    (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || isDigit(c)
    || SYMBOL_PUNCT.has(c);

// The escapes a conforming R6RS writer emits.  The reader took n t r "
// and backslash and nothing else, so a form feed inside a stored value
// could be written and then never read back, with nothing reporting a
// problem.  \x<hex>; is deliberately absent from this table: it is the
// one escape of VARIABLE length and is read by hexEscapeAt.
const STRING_ESCAPES = new Map([
    ['a', '\x07'], ['b', '\b'], ['t', '\t'], ['n', '\n'],
    ['v', '\v'], ['f', '\f'], ['r', '\r'],
    ['"', '"'], ['\\', '\\']
]);

const hexVal = c => {
    if (c >= '0' && c <= '9') return c.charCodeAt(0) - 48;
    if (c >= 'a' && c <= 'f') return c.charCodeAt(0) - 87;
    if (c >= 'A' && c <= 'F') return c.charCodeAt(0) - 55;
    return -1;
};

// \x<hex>; is the one escape whose length is not fixed.  Every other
// escape advances exactly two characters and both readers had that
// constant written into the loop, so this one carries its own end out
// rather than inheriting it.  ARR is an array of code points and K
// indexes the backslash.  Answers [codepoint, indexAfterSemicolon].
function hexEscapeAt(arr, k, fail, base) {
    let m = k + 2;
    let v = 0;
    let digits = 0;
    for (;;) {
        if (m >= arr.length) fail('unterminated hex escape', base + k);
        const d = arr[m];
        if (d === ';') break;
        const x = hexVal(d);
        if (x < 0) fail('bad hex escape', base + k);
        v = v * 16 + x;
        // bounded while the digits are consumed, not after: a long run
        // of them would otherwise build an unbounded integer before
        // anything looked at its value
        if (v > 0x10FFFF) fail('hex escape out of range', base + k);
        digits++;
        m++;
    }
    if (digits === 0) fail('hex escape with no digits', base + k);
    if (v >= 0xD800 && v <= 0xDFFF) fail('hex escape names a surrogate', base + k);
    return [v, m + 1];
}

// [-]digits, or [-]digits/digits -- the whole numeric grammar.  No
// decimal point, no exponent: a flonum crosses only as #f8"...".
function tokenToNumber(tok) {
    const neg = tok.startsWith('-');
    const body = neg ? tok.slice(1) : tok;
    if (body.length === 0) return null;
    const slash = body.indexOf('/');
    const digitsOnly = s => s.length > 0 && [...s].every(isDigit);
    if (slash >= 0) {
        const n = body.slice(0, slash), d = body.slice(slash + 1);
        if (!digitsOnly(n) || !digitsOnly(d)) return null;
        const den = BigInt(d);
        if (den === 0n) return null;          // "bad number", not a ratio
        return ratio(neg ? -BigInt(n) : BigInt(n), den);
    }
    if (!digitsOnly(body)) return null;
    return neg ? -BigInt(body) : BigInt(body);
}

// A token that STARTS like a number must BE one: this is what stops
// `1.5` or `1e9` from arriving as a symbol.
const numericShape = tok =>
    tok.length > 0 && (isDigit(tok[0])
                       || (tok[0] === '-' && tok.length > 1 && isDigit(tok[1])));

// ---------------------------------------------------------------- //
// read
// ---------------------------------------------------------------- //

const DEPTH_OPTS = Object.freeze(['maxDepth']);

export function read(text, opts = {}) {
    if (typeof text !== 'string')
        throw new TypeError('read wants a string');
    opts = checkOpts(opts, DEPTH_OPTS, {}, 'read');
    const maxDepth = opts.maxDepth === undefined ? MAX_DEPTH : opts.maxDepth;
    checkDepth(maxDepth);
    // Indexed by CODE POINT, not by UTF-16 unit: the authority counts
    // code points, so an astral character would otherwise shift every
    // position and token length after it by one.
    const cp = Array.from(text);
    const n = cp.length;
    let i = 0;

    const fail = (msg, at = i) => { throw new SexprError(msg, at); };
    const skip = () => { while (i < n && isWs(cp[i])) i++; };
    const slice = (a, b) => cp.slice(a, b).join('');

    function parseValue(depth) {
        if (depth > maxDepth) fail('nesting too deep');
        skip();
        if (i >= n) fail('unexpected end of input');
        const c = cp[i];
        if (c === '(') { i++; return parseList(depth); }
        if (c === ')') fail('unexpected )');
        if (c === '"') { i++; return parseString(); }
        if (c === '#') { i++; return parseHash(depth); }
        return parseAtom();
    }

    function parseList(depth) {
        const acc = [];
        for (;;) {
            skip();
            if (i >= n) fail('unterminated list');
            if (cp[i] === ')') { i++; return acc; }
            // a lone dot, with something already in hand: a dotted tail
            if (cp[i] === '.' && (i + 1 >= n || isDelim(cp[i + 1]))
                && acc.length > 0) {
                i++;
                const tail = parseValue(depth + 1);
                skip();
                if (i >= n || cp[i] !== ')') fail('expected ) after dotted tail');
                i++;
                // (a . ()) is (a) and (a . (b c)) is (a b c): the dot is
                // spelling, not a distinct datum
                return dotted(acc, tail);
            }
            acc.push(parseValue(depth + 1));
        }
    }

    function parseString() {
        let out = '';
        for (;;) {
            if (i >= n) fail('unterminated string');
            const c = cp[i];
            if (c === '"') { i++; return out; }
            if (c === '\\') {
                if (i + 1 >= n) fail('dangling escape');
                const e = cp[i + 1];
                // lowercase only: R6RS spells the inline hex escape
                // \x and lets only its DIGITS vary in case.  Chez
                // refuses "\X41;" outright.
                if (e === 'x') {
                    const [v, next] = hexEscapeAt(cp, i, fail, 0);
                    out += String.fromCodePoint(v);
                    i = next;
                    continue;
                }
                const lit = STRING_ESCAPES.get(e);
                if (lit === undefined) fail('bad string escape');
                out += lit;
                i += 2;
                continue;
            }
            out += c;
            i++;
        }
    }

    function parseHash(depth) {
        if (i >= n) fail('dangling #');
        const c = cp[i];
        if (c === 't' || c === 'f') {
            // #f8"..." is a flonum; #f is the boolean.  One lookahead
            // decides, and it has to be the same one the authority uses
            // or the two disagree on `#f8` with no quote after it.
            if (c === 'f' && i + 2 < n && cp[i + 1] === '8' && cp[i + 2] === '"') {
                i += 3;
                return parseFlonum();
            }
            if (!(i + 1 >= n || isDelim(cp[i + 1]))) fail('bad # literal');
            i++;
            return c === 't';
        }
        if (c === '(') { i++; return parseVector(depth); }
        if (c === 'v') {
            if (!(i + 3 < n && cp[i + 1] === 'u' && cp[i + 2] === '8'
                  && cp[i + 3] === '"')) fail('bad # literal');
            i += 4;
            return parseBytevector();
        }
        fail('bad # literal');
    }

    function parseVector(depth) {
        const acc = [];
        for (;;) {
            skip();
            if (i >= n) fail('unterminated vector');
            if (cp[i] === ')') { i++; return new Vec(acc); }
            if (cp[i] === '.' && (i + 1 >= n || isDelim(cp[i + 1])))
                fail('dot not allowed in vector');
            acc.push(parseValue(depth + 1));
        }
    }

    // Scan to the closing quote, then decode in one pass.  The base64
    // alphabet contains neither " nor \, so there is nothing to escape.
    function parseB64(what) {
        const start = i;
        for (;;) {
            if (i >= n) fail(`unterminated ${what}`, start);
            const c = cp[i];
            if (c === '"') {
                const body = slice(start, i);
                i++;
                return base64Decode(body, () => fail(`bad base64 in ${what}`, start));
            }
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || isDigit(c)
                  || c === '+' || c === '/' || c === '='))
                fail(`bad base64 in ${what}`);
            i++;
        }
    }

    function parseBytevector() { return parseB64('bytevector'); }

    function parseFlonum() {
        const start = i;
        const bytes = parseB64('flonum');
        if (bytes.length !== 8) fail('flonum wants exactly 8 bytes', start);
        return b64ToFlonum(bytes);
    }

    // A symbol may carry \x<hex>; and nothing else: the string escapes
    // are not identifier syntax.  The decoded name is held to the
    // SYMBOL GRAMMAR -- the characters a bare name may be spelled with
    // -- and that is NOT the same as wire-safe.  \x31; decodes to the
    // name 1, which the grammar admits and wireSymbol refuses, so the
    // reader can make a symbol the writer will not serialise.  R6RS
    // makes the escape identifier syntax, so reading it as the symbol
    // 1 is correct and the asymmetry lives in the writer's wire rule;
    // the vector table pins both sides of that boundary.
    function decodeName(arr, start) {
        let out = '';
        for (let k = 0; k < arr.length;) {
            const c = arr[k];
            if (c !== '\\') { out += c; k++; continue; }
            if (arr[k + 1] !== 'x') fail('bad symbol escape', start + k);
            const [v, next] = hexEscapeAt(arr, k, fail, start);
            out += String.fromCodePoint(v);
            k = next;
        }
        if (out.length === 0 || ![...out].every(isSymbolChar))
            fail('bad token', start);
        return out;
    }

    function parseAtom() {
        const start = i;
        while (i < n && !isDelim(cp[i])) i++;
        if (i - start > MAX_TOKEN) fail('token too long', start);
        const tok = slice(start, i);
        // An escaped name is a NAME.  \x31; is the symbol 1, not the
        // number, so a token carrying an escape skips the numeric
        // tests rather than being read as whatever it spells.
        if (tok.indexOf('\\') >= 0) {
            return new Sym(decodeName(cp.slice(start, i), start));
        }
        const num = tokenToNumber(tok);
        if (num !== null) return num;
        if (numericShape(tok)) fail('bad number', start);
        if (tok.length > 0 && [...tok].every(isSymbolChar)) return new Sym(tok);
        fail('bad token', start);
    }

    const v = parseValue(0);
    // the position is where the datum ended, NOT where the next one
    // begins: "1   2" points at 1, so the caller sees which datum was
    // complete rather than where the surprise was noticed
    const end = i;
    skip();
    if (i !== n) fail('trailing data after datum', end);
    return v;
}

// ---------------------------------------------------------------- //
// write
// ---------------------------------------------------------------- //

// A symbol may cross only if the wire text reads back as THAT symbol.
// This grammar has no |escaped| symbol form, so a name that reads back
// as something else would deform in transit, and the writer refuses it
// instead.  Two rules, because the two implementations of "something
// else" do not coincide:
//
//   1. The name is a number to a Scheme READER -- `12`, `+1`, `.5`,
//      `1e3`, `1/2`, `+inf.0`.  This is the authority's own criterion
//      (it asks its host's string->number) and this regex reproduces
//      its answer on every probe in the fixture's write_reject set.
//   2. The name merely STARTS numeric without being a number in this
//      grammar -- `0x10`, `12abc`.  The reader refuses those outright
//      ("bad number"), so writing one produces a datum the peer cannot
//      read at all.
//
// Rule 2 matches the authority, which asks the same question (its
// reader's numeric-shape test).  It did not always: it used to ask its
// host reader, which does not call `0x10` a number, and so emitted
// names its own parser then refused -- five of them.  That is closed
// upstream and the fixture, regenerated against the source, records no
// such name.  The suites still assert that set is empty, because it is
// the kind of hole that reopens quietly.
// "a Scheme reader would call this name a number".  Built from the
// number grammar rather than guessed at, because the shapes that get
// missed are the ones nobody thinks of: `+i` and `-i` are numbers, so
// is `+1@2` (polar) and `+inf.0+inf.0i`.  A ratio with a zero
// denominator is NOT one -- `+1/0` reads back as a symbol and may
// cross.  Every case here is pinned against the authority's own
// verdict in the fixture's write_reject group.
// Every alphabetic part of the number grammar is case-insensitive,
// because the host reader is: the exponent marker (e/s/f/d/l for the
// short/single/double/long precisions), the specials inf.0 and nan.0,
// and the imaginary suffix i.  Each of those three was missing once
// and found by the authority's verdict rather than by reading -- on
// `+1s3`, on `+NaN.0`, and on `+I`.
const UREAL = String.raw`(?:\d+\/\d*[1-9]\d*|(?:\d+\.?\d*|\.\d+)(?:[esfdlESFDL][+-]?\d+)?)`;
const INFNAN = String.raw`(?:[iI][nN][fF]|[nN][aA][nN])\.0`;
const REAL = String.raw`(?:[+-]?${UREAL}|[+-]${INFNAN})`;
const IMAGINARY = String.raw`[+-](?:${UREAL}|${INFNAN})?[iI]`;
const HOST_NUMBER = new RegExp(
    String.raw`^(?:${REAL}(?:${IMAGINARY})?|${IMAGINARY}|${REAL}@${REAL})$`);

// A caller may ask for a SMALLER depth limit -- that only narrows what
// this side accepts.  A larger one is refused: the reader on the far
// end has the authority's 64, so a deeper datum would leave here and
// be unreadable there, which is the one thing this writer promises not
// to do.  Infinity and NaN are refused for the same reason and one
// more: they would disable the guard that stops a cyclic value.
function checkDepth(d) {
    if (!Number.isInteger(d) || d < 0 || d > MAX_DEPTH)
        throw new RangeError(
            `maxDepth must be an integer in [0, ${MAX_DEPTH}]; the peer's `
            + 'reader will not go deeper than that');
}

export function wireSymbol(name) {
    if (typeof name !== 'string' || name.length === 0) return false;
    if (name === '.') return false;
    const cp = [...name];
    // before the character walk, because it is one comparison and the
    // walk is not: a name past the reader's token cap comes back as
    // "token too long" at the far end, so the writer refuses it here
    // for the same reason it refuses the numeric shapes
    if (cp.length > MAX_TOKEN) return false;
    if (!cp.every(isSymbolChar)) return false;
    if (HOST_NUMBER.test(name)) return false;      // rule 1
    if (numericShape(name)) return false;          // rule 2
    return true;
}

export function write(value, opts = {}) {
    opts = checkOpts(opts, DEPTH_OPTS, {}, 'write');
    const maxDepth = opts.maxDepth === undefined ? MAX_DEPTH : opts.maxDepth;
    checkDepth(maxDepth);
    const out = [];
    emit(value, out, 0, maxDepth);
    return out.join('');
}

// Exact integers and ratios reach the wire as their printed numeral,
// and the reader will not accept one past the token cap.  Same limit,
// same constant, both ends -- a numeral that crossed would come back
// as "token too long" at the far end.
function putNumeral(out, text) {
    if (text.length > MAX_TOKEN)
        throw new SexprError(
            'token too long for the wire -- carry a value this large as a '
            + 'bytevector (#vu8)', 0);
    out.push(text);
}

function emit(x, out, depth, maxDepth) {
    // A cycle has no depth of its own -- it just never ends -- so the
    // depth limit is what stops it, and the message says so rather
    // than blaming the data's shape.
    if (depth > maxDepth) throw new SexprError('nesting too deep (cyclic data?)', 0);
    if (Array.isArray(x)) {
        if (x.length === 0) { out.push('()'); return; }
        // the authority bounds the SPINE as well as the depth: a cycle
        // along the tail never nests, so a depth counter alone would
        // spin forever.  Same limit here, so the two writers refuse
        // the same lists.
        // the authority counts TAIL STEPS past the first element, so
        // 1,000,001 heads pass and 1,000,002 do not
        if (x.length - 1 > MAX_SPINE)
            throw new SexprError('list too long (cyclic data?)', 0);
        const items = denseElements(x);
        out.push('(');
        for (let k = 0; k < items.length; k++) {
            if (k > 0) out.push(' ');
            emit(items[k], out, depth + 1, maxDepth);
        }
        out.push(')');
        return;
    }
    if (x instanceof DottedList) {
        if (x.items.length - 1 > MAX_SPINE)
            throw new SexprError('list too long (cyclic data?)', 0);
        out.push('(');
        for (let k = 0; k < x.items.length; k++) {
            if (k > 0) out.push(' ');
            emit(x.items[k], out, depth + 1, maxDepth);
        }
        out.push(' . ');
        emit(x.tail, out, depth + 1, maxDepth);
        out.push(')');
        return;
    }
    if (x instanceof Sym) {
        if (!wireSymbol(x.name)) throw new SexprError('symbol not wire-safe', 0);
        out.push(x.name);
        return;
    }
    if (typeof x === 'string') {
        // only " and \ are escaped; a literal newline inside a string
        // is legal on this wire
        // A lone surrogate has no UTF-8 encoding: it would survive as a
        // JS string and become U+FFFD the moment these characters are
        // encoded for the wire, so the bytes sent would not be the
        // value that was accepted here.  Refused rather than mangled.
        for (let k = 0; k < x.length; k++) {
            const u = x.charCodeAt(k);
            if (u >= 0xd800 && u <= 0xdbff) {
                const next = x.charCodeAt(k + 1);
                if (!(next >= 0xdc00 && next <= 0xdfff))
                    throw new SexprError('string holds an unpaired surrogate', 0);
                k++;
            } else if (u >= 0xdc00 && u <= 0xdfff) {
                throw new SexprError('string holds an unpaired surrogate', 0);
            }
        }
        out.push('"');
        for (const c of x) {
            if (c === '"' || c === '\\') out.push('\\');
            out.push(c);
        }
        out.push('"');
        return;
    }
    if (x === true) { out.push('#t'); return; }
    if (x === false) { out.push('#f'); return; }
    if (typeof x === 'bigint') { putNumeral(out, x.toString()); return; }
    if (x instanceof Ratio) {
        // ratio() cannot produce these, but a hand-built object can:
        // an unnormalized or integral one would read back as a
        // different value on the peer
        if (x.den <= 0n || x.num % 1n !== 0n)
            throw new SexprError('ratio is not normalized', 0);
        if (x.den === 1n) throw new SexprError('ratio reduces to an integer', 0);
        if (gcd(x.num < 0n ? -x.num : x.num, x.den) !== 1n)
            throw new SexprError('ratio is not in lowest terms', 0);
        putNumeral(out, `${x.num}/${x.den}`);
        return;
    }
    if (x instanceof Vec) {
        out.push('#(');
        for (let k = 0; k < x.items.length; k++) {
            if (k > 0) out.push(' ');
            emit(x.items[k], out, depth + 1, maxDepth);
        }
        out.push(')');
        return;
    }
    if (x instanceof Uint8Array) {
        out.push('#vu8"', base64Encode(x), '"');
        return;
    }
    if (typeof x === 'number') {
        out.push('#f8"', flonumToB64(x), '"');
        return;
    }
    // everything else by name, so a caller learns which value it was
    if (x === null) throw new SexprError('null is not a wire datum', 0);
    if (x === undefined) throw new SexprError('undefined is not a wire datum', 0);
    if (ArrayBuffer.isView(x))
        throw new SexprError('only Uint8Array crosses as a bytevector', 0);
    throw new SexprError('datum not in the wire whitelist', 0);
}

// ---------------------------------------------------------------- //
// the JSON view: lossy, but never quietly
// ---------------------------------------------------------------- //
//
// JSON has no symbols, no exact integers past 2^53, no ratios, no
// bytes and no dotted pairs.  Three of those convert unconditionally,
// because the conversion loses nothing a JSON consumer could act on:
// a Sym becomes its name, a Vec becomes an array, and an exact integer
// inside the safe range becomes a number.  The rest are refusals by
// default, with an opt-in that says what is being given up:
//
//   opts.bigint : 'string'   BigInt past 2^53-1 becomes a string
//   opts.ratio  : 'number'   Ratio becomes its quotient as a double
//   opts.bytes  : 'base64'   Uint8Array becomes a base64 string
//   opts.alist  : false      turn off the alist-to-object rule
//
// The alist rule: a non-empty array whose every element is a dotted
// pair with a single Sym head becomes an object.  Anything else that
// is dotted is refused -- "some of it looks like an object" is exactly
// the shape that would silently lose half a payload.

const SAFE = 9007199254740991n;

// num/den as a double.  Converting the two operands and dividing gets
// 10^400/(10^400+1) wrong -- both become Infinity and the quotient is
// NaN, a false refusal for a ratio whose value is 1.  Divide in BigInt
// first, then scale the remainder.
function bitLength(x) {
    let n = 0;
    while (x > 0n) { x >>= 1n; n++; }
    return n;
}

// Scale by however much THIS ratio needs, not by a fixed amount: a
// fixed 2^-64 fractional step silently rounds every value below it to
// zero, so 1/(2^100+1) came out as 0 instead of 7.9e-31.  Shift the
// numerator until the integer quotient carries ~60 significant bits,
// then undo the shift in the double.
function ratioToDouble(num, den) {
    if (num === 0n) return 0;
    const neg = (num < 0n) !== (den < 0n);
    const n = num < 0n ? -num : num;
    const d = den < 0n ? -den : den;
    const shift = BigInt(Math.max(0, bitLength(d) - bitLength(n) + 60));
    const q = Number((n << shift) / d);
    // 2**-shift as a double; for shifts past the exponent range the
    // product is zero or infinite, which is the honest answer
    const scaled = q * Math.pow(2, -Number(shift));
    return neg ? -scaled : scaled;
}

// Frozen: an exported array is a whitelist a caller can push onto, and
// `TO_JSON_OPTS.push('alists')` would make the typo validate and then
// be ignored -- the check defeating itself.
export const TO_JSON_OPTS = Object.freeze(['bigint', 'ratio', 'bytes', 'alist']);
const TO_JSON_OPT_VALUES = {
    bigint: ['string'],
    ratio: ['number'],
    bytes: ['base64'],
    alist: [true, false],
};

// The option bag itself, and every value in it.  `{alist: 'false'}` and
// `{alist: 0}` are not `false`: they left the rule ON and changed the
// result's shape, which is the same silent difference a misspelt key
// makes.  A bag that is not a plain object is a mistake too.
// -> a frozen snapshot of the validated options.  Callers use the
// SNAPSHOT, never the caller's object: validating one thing and then
// reading another is how an accessor slips a different value in after
// the check, and a non-enumerable or inherited key is honoured by a
// plain property read while `Object.keys` never saw it.
function checkOpts(opts, allowed, values, who) {
    if (opts === null || typeof opts !== 'object' || Array.isArray(opts)
        || Object.prototype.toString.call(opts) !== '[object Object]')
        throw new TypeError(`${who} wants a plain options object`);
    // every own key, enumerable or not, string or symbol: a property a
    // consumer can read is a property that must be validated
    const syms = Object.getOwnPropertySymbols(opts);
    if (syms.length)
        throw new TypeError(`${who}: options are named with strings, not symbols`);
    const snapshot = {};
    for (const k of Object.getOwnPropertyNames(opts)) {
        if (!allowed.includes(k))
            throw new TypeError(
                `unknown option "${k}": ${who} takes `
                + allowed.map(a => `"${a}"`).join(', '));
        const v = opts[k];                       // read ONCE
        const ok = values[k];
        if (ok && !ok.includes(v))
            throw new TypeError(
                `option "${k}" takes ${ok.map(x => JSON.stringify(x)).join(' or ')}`
                + `, not ${JSON.stringify(v)}`);
        snapshot[k] = v;
    }
    // an inherited option would be read by a consumer and never checked
    for (const k of allowed)
        if (!Object.hasOwn(opts, k) && opts[k] !== undefined)
            throw new TypeError(
                `option "${k}" is inherited, not this object's; pass it directly`);
    return Object.freeze(snapshot);
}

export function toJSON(v, opts = {}) {
    const bad = m => { throw new TypeError(m); };
    // A misspelt option that silently means something else is the same
    // failure this codec refuses everywhere else.
    opts = checkOpts(opts, TO_JSON_OPTS, TO_JSON_OPT_VALUES, 'toJSON');
    // fromJSON refuses a cycle by name; without the same book-keeping
    // here the two directions disagree and a self-referential value
    // exhausts the host stack instead of being reported
    const seen = new Set();
    const go = x => {
        if (x !== null && typeof x === 'object') {
            if (seen.has(x)) return bad('this structure contains a cycle');
            seen.add(x);
            try { return go1(x); } finally { seen.delete(x); }
        }
        return go1(x);
    };
    const go1 = x => {
        if (x instanceof Sym) return x.name;
        if (typeof x === 'string') return x;
        if (typeof x === 'boolean') return x;
        if (typeof x === 'bigint') {
            if (x <= SAFE && x >= -SAFE) return Number(x);
            if (opts.bigint === 'string') return x.toString();
            return bad(`exact integer ${x} exceeds JSON's safe range; `
                       + `pass {bigint:'string'} to accept the loss`);
        }
        if (typeof x === 'number') {
            if (!Number.isFinite(x))
                return bad(`${x} has no JSON representation`);
            return x;
        }
        if (x instanceof Ratio) {
            if (opts.ratio === 'number') {
                const q = ratioToDouble(x.num, x.den);
                // the opt-in accepts LOSS of exactness, not loss of the
                // value: a ratio too big for a double has no JSON
                // number, which the branch above refuses too
                if (!Number.isFinite(q))
                    return bad(`ratio ${x.num}/${x.den} has no finite double; `
                               + 'it cannot cross as a JSON number');
                return q;
            }
            return bad(`ratio ${x.num}/${x.den} has no JSON representation; `
                       + `pass {ratio:'number'} to accept the loss`);
        }
        if (x instanceof Uint8Array) {
            if (opts.bytes === 'base64') return base64Encode(x);
            return bad(`bytevector has no JSON representation; `
                       + `pass {bytes:'base64'} to accept the loss`);
        }
        if (x instanceof Vec) return mapDense(x.items, go);
        if (Array.isArray(x)) {
            const elements = denseElements(x);
            if (opts.alist !== false && elements.length > 0
                && elements.every(isAlistPair)) {
                // null prototype: a key named __proto__, constructor or
                // toString must be data here, not a reach into
                // Object.prototype -- and the duplicate check has to be
                // an own-key question for the same reason
                const o = Object.create(null);
                for (const p of elements) {
                    const k = p.items[0].name;
                    if (Object.hasOwn(o, k))
                        return bad(`duplicate key "${k}" in alist`);
                    o[k] = go(p.tail);
                }
                return o;
            }
            return elements.map(go);
        }
        if (x instanceof DottedList)
            return bad('a dotted pair that is not part of an alist has no '
                       + 'JSON representation');
        return bad(`no JSON representation for ${typeof x}`);
    };
    return go(v);
}

// Array.prototype.map keeps a hole as a hole (JSON.stringify turns it
// into null) and copies an inherited index in as own data.  Either
// would leave this direction disagreeing with fromJSON, which refuses
// a hole outright.
function mapDense(a, f) {
    return denseElements(a).map(f);
}

// The one place that decides what an array's elements ARE.  Every
// other walk goes through it, because the built-ins do not agree with
// each other: `map` keeps a hole as a hole, `every` and `for…of` read
// straight through to the prototype, and a spread copies an inherited
// index in as own data.  A hole has no wire datum, and an inherited
// index is not this array's data, so both are refused here rather than
// silently meaning something in one walk and something else in another.
export function denseElements(a) {
    const out = [];
    for (let k = 0; k < a.length; k++) {
        if (!Object.hasOwn(a, k))
            throw new TypeError(
                `index ${k} is a hole; there is no wire datum for it`);
        out.push(a[k]);
    }
    return out;
}

// The name of the built-in whose internal slots this object has, or
// null when it has none.  Each probe calls a method that only works on
// a genuine instance.
const BRANDS = [
    ['Map', v => Map.prototype.has.call(v, 0)],
    ['Set', v => Set.prototype.has.call(v, 0)],
    ['Date', v => Date.prototype.getTime.call(v)],
    ['RegExp', v => RegExp.prototype.exec.call(v, '')],
    ['WeakMap', v => WeakMap.prototype.has.call(v, {})],
    ['WeakSet', v => WeakSet.prototype.has.call(v, {})],
    ['Promise', v => Promise.prototype.then.call(v, () => {}, () => {})],
    ['Number', v => Number.prototype.valueOf.call(v)],
    ['String', v => String.prototype.valueOf.call(v)],
    ['Boolean', v => Boolean.prototype.valueOf.call(v)],
    ['Symbol', v => Symbol.prototype.valueOf.call(v)],
    ['BigInt', v => BigInt.prototype.valueOf.call(v)],
];
function exoticBrand(v) {
    if (ArrayBuffer.isView(v) || v instanceof ArrayBuffer) return 'a typed array';
    for (const [name, probe] of BRANDS) {
        try { probe(v); return name; } catch { /* not this one */ }
    }
    return null;
}

const isAlistPair = p =>
    p instanceof DottedList && p.items.length === 1 && p.items[0] instanceof Sym;

// The other direction.  A safe integer becomes an EXACT integer, which
// is what a Scheme peer means by 42; anything else finite becomes a
// flonum -- with one deliberate exception, -0, which is a safe integer
// but has no exact form carrying its sign, so it crosses as a flonum
// where the wire can hold the sign bit.  null is refused: there is no wire datum that round-trips
// back to it, and inventing one ('() or #f) would silently change a
// payload's meaning.
// The cycle set is not reachable from outside: exposing it as a second
// parameter meant `args.map(fromJSON)` handed it an index (every
// structured rpc argument died), and later that a caller could pass a
// set already containing the input and make acyclic data report a
// cycle.  An accumulator belongs in the private entry point.
export function fromJSON(j) {
    if (arguments.length > 1)
        throw new TypeError('fromJSON takes one argument');
    return fromJSON1(j, new Set());
}

function fromJSON1(j, seen) {
    if (typeof j === 'string') return j;
    if (typeof j === 'boolean') return j;
    if (typeof j === 'number') {
        // -0 IS distinguishable in JSON (JSON.parse("-0") is -0) and the
        // wire carries a signed zero bit-exactly, so it crosses as a
        // flonum rather than collapsing into the exact 0 that BigInt(-0)
        // would give.
        if (Object.is(j, -0)) return -0;
        if (Number.isSafeInteger(j)) return BigInt(j);
        if (!Number.isFinite(j))
            throw new TypeError(`${j} cannot cross this wire`);
        return j;
    }
    if (typeof j === 'bigint') return j;
    if (j === null)
        throw new TypeError('null has no wire representation; send #f or () '
                            + 'explicitly if that is what you mean');
    if (j === undefined)
        throw new TypeError('undefined has no wire representation');
    // already-faithful values pass straight through, so a caller can
    // mix precise data into a JSON-shaped payload
    if (j instanceof Sym || j instanceof Ratio || j instanceof Vec
        || j instanceof Uint8Array || j instanceof DottedList) return j;
    if (typeof j === 'function')
        throw new TypeError('no wire representation for a function');
    if (typeof j === 'symbol')
        throw new TypeError('no wire representation for a JS symbol; '
                            + 'use sym() for a wire symbol');
    if (typeof j === 'object') {
        // Only a PLAIN object is a JSON object.  A Map, a Set, a Date, a
        // RegExp or a boxed primitive has no own enumerable string keys
        // to speak of, so Object.entries answers `[]` and the payload
        // disappears without a word -- the loss this direction exists to
        // refuse.
        // BRAND checks, not Object.prototype.toString: that string is
        // whatever Symbol.toStringTag says, so a Map wearing the tag
        // 'Object' would pass and lose its entries, while an ordinary
        // object wearing another tag would be refused.  These probes
        // read an internal slot, which no tag can fake.
        if (!Array.isArray(j)) {
            const brand = exoticBrand(j);
            if (brand)
                throw new TypeError(
                    `no wire representation for ${brand}; build the value with `
                    + 'sym/Vec/DottedList or convert it first');
        }
        // an array can carry one too, and it used to return before the
        // check below ever ran
        for (const sk of Object.getOwnPropertySymbols(j))
            if (Object.getOwnPropertyDescriptor(j, sk).enumerable)
                throw new TypeError(
                    `value has the symbol key ${String(sk)}, which has no wire `
                    + 'representation; remove it or use a string key');
        if (seen.has(j)) throw new TypeError('this structure contains a cycle');
        seen.add(j);
        try {
            if (Array.isArray(j)) {
                // ONE pass: denseElements refuses holes and reads each
                // own element as it checks it.  Validating first and
                // walking again would let a getter delete an element in
                // between, and the second walk would then read straight
                // through to Array.prototype.
                return denseElements(j).map(x => fromJSON1(x, seen));
            }
            // an object becomes an alist in Object.keys order -- own
            // enumerable keys only, in insertion order for string keys,
            // so the peer sees the order the caller wrote
            // the key/value pairs are snapshotted together, for the
            // same reason: reading keys and then reading values is two
            // passes over something a getter can change
            return Object.entries(j).map(([k, value]) => {
                // a key that is not a wire-safe symbol name would be
                // refused later by write(); saying so HERE names the
                // key, which the writer no longer can
                if (!wireSymbol(k))
                    throw new TypeError(
                        `object key ${JSON.stringify(k)} is not a wire-safe `
                        + 'symbol name (it would read back as a number or not '
                        + 'at all); rename it or build the alist yourself');
                return dotted([new Sym(k)], fromJSON1(value, seen));
            });
        } finally { seen.delete(j); }
    }
    throw new TypeError(`no wire representation for ${typeof j}`);
}

// ---------------------------------------------------------------- //
// rpc
// ---------------------------------------------------------------- //
//
// One POST, one datum out, one datum back.  The tag is a symbol and the
// arguments go through fromJSON, so a caller can write
// rpc(url, 'get-user', 42) and get exactness right by default.
//
// An (error ...) reply is DATA, not a rejection: the peer answered, and
// what it said is the answer.  The promise fails for the transport (a
// network error, a non-2xx status) and for a reply that is not this
// wire at all -- bytes that are not UTF-8, or text that does not
// parse.  What the peer MEANT is never a rejection; what it sent
// being unreadable is.

export async function rpc(url, tag, ...args) {
    const body = write([new Sym(tag), ...args.map(a => fromJSON(a))]);
    const res = await globalThis.fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/sexpr' },
        body,
    });
    if (!res.ok) {
        const e = new Error(`rpc ${tag}: HTTP ${res.status}`);
        e.status = res.status;
        throw e;
    }
    // NOT res.text(): its decoder replaces malformed bytes with U+FFFD,
    // so a reply carrying `22 ff 22` would arrive as the string "\uFFFD"
    // instead of being refused.  A wire that is not UTF-8 is not this
    // wire.
    const bytes = new Uint8Array(await res.arrayBuffer());
    let text;
    try {
        text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
    } catch {
        throw new SexprError('reply is not valid UTF-8', 0);
    }
    return read(text);
}

export async function rpcJSON(url, tag, ...args) {
    return toJSON(await rpc(url, tag, ...args));
}
